            groups[p - i] += p
        return max(groups.values())

class Solution {
public:
    long long maxScore(vector<int>& prices) {
        unordered_map<int, long long> groups;
        long long ans = 0;
        for (int i = 0; i < prices.size(); i++) {
            int key = prices[i] - i;
            groups[key] += prices[i];
            ans = max(ans, groups[key]);
        }
        return ans;
    }
};

class Solution {
    public long maxScore(int[] prices) {
        Map<Integer, Long> groups = new HashMap<>();
        long ans = 0;
        for (int i = 0; i < prices.length; i++) {
            int key = prices[i] - i;
            long total = groups.getOrDefault(key, 0L) + prices[i];
            groups.put(key, total);
            if (total > ans) ans = total;
        }
        return ans;
    }
}

/**
 * @param {number[]} prices
 * @return {number}
 */
var maxScore = function(prices) {
    const groups = new Map();
    let ans = 0;
    for (let i = 0; i < prices.length; i++) {
        const key = prices[i] - i;
        const total = (groups.get(key) || 0) + prices[i];
        groups.set(key, total);
        if (total > ans) ans = total;
    }
    return ans;
};
